import unittest
from queue_cli import format_records

class QueueTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(format_records([]), "")

    def test_input_order(self):
        self.assertEqual(format_records([{"id": "b"}, {"id": "a"}]), '{"id": "b"}\n{"id": "a"}\n')
